function csv(rows:Row[],columns:string[],file:string){const esc=(s:any)=>'"'+String(s??'').replace(/"/g,'""')+'"',data=[['Name',...columns.map(human)],...rows.map(r=>[r.name,...columns.map(k=>r[k])])].map(r=>r.map(esc).join(',')).join('\n');const u=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=file+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);}
