 const noSort=box||fixedOrder,warModel=useContext(WarModelContext),rows=useMemo(()=>sourceRows.map(row=>withWobaWar(row,warModel)),[sourceRows,warModel]);const [cols,choose]=useSavedSelection('fs:columns:'+context,columns);const viewsId=namedViews??context;const [sort,setSort]=useState({key:sortBy,dir:['era','fip','xfip','whip','order'].includes(sortBy)?1:-1}),[page,setPage]=useState(0),[size,setSize]=useState(50),[edit,setEdit]=useState(false),[filter,setFilter]=useState(''),[columnGroup,setColumnGroup]=useState(box?'Game':'All stats'),[viewName,setViewName]=useState(''),[savedViews,setSavedViews]=useState<Row>({});
 const available=useMemo(()=>pairedColumns([...new Set([...columns,...rows.flatMap(r=>Object.keys(r).filter(k=>!META.has(k)&&(r[k]===null||r[k]!==undefined&&typeof r[k]!=='object')))])]).filter(k=>playoffsAllowed||!k.startsWith('playoff')),[rows,columns.join(','),playoffsAllowed]);
