function pitchTone(p:Row){const t=String(p.description??p.call??'').toLowerCase();return t.includes('in play')?'contact':(t.includes('ball')&&!t.includes('foul')||t.includes('hit by pitch'))?'ball':t.includes('foul')?'foul':'strike'}
function StrikeZone({pitches}:{pitches:Row[]}){return <PitchZone pitches={pitches}/> }

function PitchTable({rows}:{rows:Row[]}){return <div className="table-scroll"><table><thead><tr>{['Inning','#','Batter','Pitcher','Pitch','Result','Count','Velo','Spin','EV','LA','Distance','xBA','pX','pZ'].map(k=><th key={k}>{k}</th>)}</tr></thead><tbody>{rows.map((p,i)=><tr key={i}><td>{p.inning??'—'}</td><td>{p.number}</td><td>{p.batter??'—'}</td><td>{p.pitcher??'—'}</td><td>{p.type??'Unknown'}</td><td className={'pitch-result '+pitchTone(p)}>{p.description??p.call??'—'}</td><td>{p.balls}–{p.strikes}</td><td>{fmt('velocity',p.velocity)}</td><td>{fmt('spin',p.spin)}</td><td>{fmt('ev',p.ev)}</td><td>{fmt('la',p.la)}</td><td>{fmt('distance',p.distance)}</td><td>{fmt('xba',p.xba)}</td><td>{fmt('x',p.x)}</td><td>{fmt('z',p.z)}</td></tr>)}</tbody></table>{!rows.length&&<div className="empty">Pitch detail has not been reported for this play.</div>}</div>}
function ContactPlot({rows}:{rows:Row[]}){const pts=rows.filter(x=>x.ev!==null&&x.la!==null);return <svg className="contact-plot" viewBox="0 0 720 230" role="img" aria-label="Exit velocity and launch angle of measured batted balls">{[0,20,40,60].map(t=><g key={t}><line x1="35" x2="690" y1={185-t*2.5} y2={185-t*2.5}/><text x="5" y={189-t*2.5}>{t}°</text></g>)}{[50,70,90,110].map(t=><text key={t} x={35+(t-40)*7.5} y="215">{t}</text>)}{pts.map((p,i)=><circle key={i} cx={35+Math.max(0,Math.min(87,p.ev-40))*7.5} cy={185-Math.max(-8,Math.min(70,p.la))*2.5} r="3.4" fill={p.ev>=95?'#c15933':'#30638b'} opacity=".65"><title>{p.date} {p.event} · {p.ev} mph · {p.la}°</title></circle>)}<text x="690" y="228" textAnchor="end">Exit velocity (mph)</text></svg>}
