 const splitRows=(p?.splits??[]).map((s:Row)=>{const k=({all:'ALL',vl:'L',vr:'R',h:'home',a:'away'} as Row)[s.split],sc=csvData.data?.splits?.[k];return {...s,...(contact.data?.summary?.[k]??{}),...(sc?{ev:sc.ev,hardhit:sc.hardhit,barrel:sc.barrel,la:sc.la,bbe:sc.bbe,xwoba:sc.xwoba,xavg:sc.xba,xslg:sc.xslg}:{}),scPA:sc?.pa,scWoba:sc?.woba,xwobaDisplay:sc?.xwoba??null,xwobaCoverage:sc?.xwobaCoverage,id:s.split,name:s.label}});
