function SavantPitchPlot({rows,breakdown}:{rows:Row[],breakdown:Row[]}){const [type,setType]=useState('all'),colors=new Map(breakdown.map(r=>[r.pitchType,r.color])),shown=rows.filter(r=>type==='all'||r.pt===type);return <><div className="filters"><Select label="Pitch type" value={type} onChange={setType} options={[["all","Every pitch"],...breakdown.map(r=>[r.pitchType,r.name])]}/><span className="subtle">{shown.length} tracked pitches · catcher’s view</span></div><svg className="savant-pitch-plot" viewBox="0 0 320 300" role="img" aria-label="Season pitch locations colored by pitch type"><rect x="132" y="118" width="56" height="90"/>{shown.slice(0,5000).map((p,i)=><circle key={i} cx={160+Number(p.x)*40} cy={275-Number(p.z)*45} r="2.4" fill={String(colors.get(p.pt)??'#67c1ff')} opacity=".55"><title>{p.pt} · {p.vel} mph · {String(p.gd).slice(0,10)}</title></circle>)}</svg><div className="pitch-color-key">{breakdown.map(r=><span key={r.pitchType}><i style={{background:r.color}}/>{r.name} {r.percent}%</span>)}</div></>}
function SavantSpray({rows}:{rows:Row[]}){return <><svg className="savant-spray" viewBox="0 0 400 380" role="img" aria-label="Tracked hit spray directions"><path className="field" d="M200 350 L35 185 Q35 30 200 30 Q365 30 365 185 Z"/><path d="M200 350 L144 294 L200 238 L256 294 Z"/>{rows.filter(p=>Number.isFinite(Number(p.x))&&Number.isFinite(Number(p.y))).map((p,i)=><circle key={i} cx={200+Number(p.x)*.65} cy={350-Number(p.y)*.65} r="3" fill={p.events==='home_run'?'#c49cff':p.events==='double'||p.events==='triple'?'#ffc35d':'#62d69d'} opacity=".7"><title>{human(p.events)} · tracked x {p.x}, y {p.y}</title></circle>)}</svg><Note>{rows.length} tracked hit locations. These are source coordinates on a schematic field, with no ballpark wall model. Missing locations are not estimated.</Note></>}
