function LiveFreshness({data,checking}:{data:Row,checking:boolean}){const [now,setNow]=useState(Date.now());useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(id)},[]);const age=Math.max(0,Math.floor((now-new Date(data.updated).getTime())/1000)),stamp=String(data.sourceTimestamp??''),source=stamp.length>=15?`${stamp.slice(0,4)}-${stamp.slice(4,6)}-${stamp.slice(6,8)} ${stamp.slice(9,11)}:${stamp.slice(11,13)}:${stamp.slice(13,15)} UTC`:null;return <div className="live-freshness" role="status"><i className={checking?'checking':''}/><b>{checking?'Checking MLB…':'Auto updates on'}</b><span>Checked {age}s ago</span>{source&&<span>MLB feed {source}</span>}<small>Updates stay in place. MLB source and network latency still apply.</small></div>}
function CareerMatchup({batterId,pitcherId,onPlayer}:{batterId?:number,pitcherId?:number,onPlayer:(id:number,kind?:string)=>void}){const [batter,setBatter]=useState(String(batterId??'')),[pitcher,setPitcher]=useState(String(pitcherId??'')),[scope,setScope]=useState('R'),[query,setQuery]=useState<Row|null>(batterId&&pitcherId?{batter:batterId,pitcher:pitcherId,gameType:'R'}:null),data=useData(query?{view:'careerMatchup',...query}:null);useEffect(()=>{if(batterId&&pitcherId){setBatter(String(batterId));setPitcher(String(pitcherId));setQuery({batter:batterId,pitcher:pitcherId,gameType:scope})}},[batterId,pitcherId]);return <Panel title="Batter–pitcher career matchup"><div className="filters"><label className="select-label"><span>Batter MLB ID</span><input type="number" min="1" value={batter} onChange={e=>setBatter(e.target.value)}/></label><label className="select-label"><span>Pitcher MLB ID</span><input type="number" min="1" value={pitcher} onChange={e=>setPitcher(e.target.value)}/></label><Select label="Career scope" value={scope} onChange={v=>{setScope(v);if(query)setQuery({...query,gameType:v})}} options={[["R","Regular season"],['P','Postseason']]}/><button onClick={()=>setQuery({batter:Number(batter),pitcher:Number(pitcher),gameType:scope})}>Compare matchup</button><button onClick={()=>{setBatter(String(batterId??''));setPitcher(String(pitcherId??''));if(batterId&&pitcherId)setQuery({batter:batterId,pitcher:pitcherId,gameType:scope})}}>Current matchup</button></div><Status resource={data}/>{data.data&&<><div className="career-matchup-names"><button onClick={()=>onPlayer(data.data.batter,'batting')}>{data.data.batterInfo?.fullName??'Batter'}</button><span>vs</span><button onClick={()=>onPlayer(data.data.pitcher,'pitching')}>{data.data.pitcherInfo?.fullName??'Pitcher'}</button></div>{data.data.totals?<EditableStats row={data.data.totals} defaults={['pa','ab','h','hr','bb','so','avg','ops','woba']} storageKey="career-matchup"/>:<Note>No career plate appearances returned in this scope.</Note>}<details className="career-season-detail"><summary>Season-by-season matchup</summary><Table rows={data.data.seasons} columns={['pa','ab','h','hr','bb','so','avg','ops','woba']} context="career-matchup-seasons" label="Season" sortBy="name"/></details><Note>{data.data.scope}. {data.data.note}</Note></>}</Panel>}

function HomeRunParks({count}:{count:number}){return <span className={"homer-parks "+(count===30?"all-parks":count>=15?"many-parks":"few-parks")} title="Official Statcast trajectory comparison against the dimensions and wall heights of 30 MLB ballparks. This is not a probability."><svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true"><path d="M3 3h14v8l-7 6-7-6Z" fill="none" stroke="currentColor" strokeWidth="1.6"/></svg>HR in <b>{count}/30</b> parks{count===30?' · All parks':''}</span>}
